function biggestLandMass(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const area = (r: number, c: number): number => {
    if (r < 0 || c < 0 || r >= R || c >= C || grid[r][c] !== 1) return 0;
    grid[r][c] = 0; // seen
    return 1 + area(r + 1, c) + area(r - 1, c) + area(r, c + 1) + area(r, c - 1);
  };
  let best = 0;
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (grid[r][c] === 1) best = Math.max(best, area(r, c));
  return best;
}

